static void cleanup(void) {
    pix_clear();
    pixa_clear();
    pixaa_clear();
    pixac_clear();
    pixc_clear();
    cmap_clear();
    pixacc_clear();
    tiling_clear();
    box_clear();
    boxa_clear();
    boxaa_clear();
    numa_clear();
    numaa_clear();
    dna_clear();
    dnaa_clear();
    dnahash_clear();
    pta_clear();
    ptaa_clear();
    sa_clear();
    fpix_clear();
    fpixa_clear();
    dpix_clear();
    sel_clear();
    sela_clear();
    kel_clear();
    ba_clear();
    recog_clear();
    dewarpa__clear();
    dewarpa_clear();
    ccba_clear();
    bmf_clear();
    classer_clear();
    jbdata_clear();
    ptra_clear();
    ptraa_clear();
    stack_clear();
    queue_clear();
    heap_clear();
    rb_clear();
    amap_clear();
    aset_clear();
    hmap_clear();
    dll_clear();
    gplot_clear();
    sudoku_clear();
    wshed_clear();
    rcha_clear();
    cid_clear();
    bb_clear();
    cfill_clear();
    wtimer_clear();
    tmp_free();
    borrow_invalidate();
    wbuf_n = 0;
    if (timer_pending) stopTimerNested(timer_pending);
    timer_pending = NULL;
    if (lineptrs_pending) lept_free(lineptrs_pending);
    lineptrs_pending = NULL;
    unlink(FNAME);
    unlink(FNAME2);
    file_written = 0;
    setMsgSeverity(L_SEVERITY_NONE);
}

int LLVMFuzzerInitialize(int *argc, char ***argv) {
    (void)argc;
    (void)argv;
    /* the harness owns the message stream: L_WARNING/L_ERROR inside a fuzz target
       would otherwise print for every failing call */
    setMsgSeverity(L_SEVERITY_NONE);
    return 0;
}

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    size_t off = 0;
    preqed_reset();
    while (size - off >= 4) {
        unsigned op = (unsigned)data[off] | (unsigned)data[off + 1] << 8;
        size_t len = (size_t)data[off + 2] | (size_t)data[off + 3] << 8;
        off += 4;
        if (len > size - off) break;
        payload in = { data + off, len };
        api[op % API_COUNT](in);
        off += len;
        trim_all();
    }
    cleanup();
    return 0;
}
